  primary: '0B1F3A',
  secondary: '1F4E79',
  accent: '2E75B6',
  light: 'EAF1FB',
  bg: 'F7FAFF'
};

function addHeader(slide, title, subtitle) {
  slide.background = { color: 'FFFFFF' };
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.65,
    fill: { color: theme.primary },
    line: { color: theme.primary }
  });
  slide.addText(title, {
    x: 0.35, y: 0.13, w: 9.2, h: 0.3,
    fontFace: 'Arial', fontSize: 14, bold: true, color: 'FFFFFF'
  });
  if (subtitle) {
    slide.addText(subtitle, {
      x: 0.35, y: 0.78, w: 9.2, h: 0.24,
      fontFace: 'Arial', fontSize: 10, color: '5B6B7A'
    });
  }
}

function addPageBadge(slide, n) {
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.32, h: 0.32,
    fill: { color: theme.accent }, line: { color: theme.accent }
  });
  slide.addText(String(n), {
    x: 9.3, y: 5.1, w: 0.32, h: 0.32,
    fontFace: 'Arial', fontSize: 10, bold: true, color: 'FFFFFF', align: 'center', valign: 'mid'
  });
}

// Slide 1 - Title
{
  const slide = pres.addSlide();
  slide.background = { color: 'FFFFFF' };
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 5.625,
    fill: { color: theme.primary }, line: { color: theme.primary }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 4.5, w: 10, h: 1.125,
    fill: { color: theme.accent }, line: { color: theme.accent }, transparency: 25
  });
  slide.addText('AI Model Landscape April 2026: Benchmarking Intelligence, Speed, and Cost Across 11 Frontier Models', {
    x: 0.6, y: 1.0, w: 8.8, h: 1.9,
    fontFace: 'Arial', fontSize: 28, bold: true, color: 'FFFFFF', align: 'left', valign: 'top'
  });
  slide.addText('Artificial Analysis snapshot (captured April 10, 2026)', {
    x: 0.6, y: 3.15, w: 8.8, h: 0.4,
    fontFace: 'Arial', fontSize: 14, color: 'DCE6F2'
  });
  slide.addText('Audience: AI engineering leads & product managers', {
    x: 0.6, y: 3.55, w: 8.8, h: 0.3,
    fontFace: 'Arial', fontSize: 12, color: 'DCE6F2'
  });
  slide.addText('Key premise: no single model dominates intelligence, throughput, and cost simultaneously.', {
    x: 0.6, y: 4.78, w: 8.8, h: 0.35,
    fontFace: 'Arial', fontSize: 12, color: 'FFFFFF', italic: true
  });
}

// Slide 2 - Intelligence
{
  const slide = pres.addSlide();
  addHeader(slide,
    'Gemini 3.1 Pro Preview and GPT-5.4 Co-Lead the Intelligence Index at 57',
    'Artificial Analysis Intelligence Index (April 2026) — full 11-model ranking'
  );

  const rows = [
    ['Rank','Model','Provider','Intelligence Index'],
    ['1','Gemini 3.1 Pro Preview','Google','57'],
    ['2','GPT-5.4 (xhigh)','OpenAI','57'],
    ['3','Claude Opus 4.6 (max)','Anthropic','53'],
    ['4','Muse Spark','Meta','52'],
    ['5','Claude Sonnet 4.6 (max)','Anthropic','52'],
    ['6','GLM-5.1','Z AI','51'],
    ['7','Grok 4.20 0309 v2','xAI','49'],
    ['8','Gemini 3 Flash','Google','46'],
    ['9','DeepSeek V3.2','DeepSeek','42'],
    ['10','NVIDIA Nemotron 3 Super','NVIDIA','36'],
    ['11','gpt-oss-120B (high)','OpenAI','33']
  ];

  slide.addTable(rows, {
    x: 0.35, y: 1.15, w: 9.25, h: 3.95,
    fontFace: 'Arial', fontSize: 10,
    border: { pt: 1, color: 'D6DEE8' },
    fill: 'FFFFFF',
    color: '1F2D3D',
    colW: [0.7, 4.2, 2.0, 2.0],
    rowH: 0.29,
    autoFit: false
  });

  slide.addText('Spread from #1 to #11: 24 points (57  33); co-leaders are tied at the frontier.', {
    x: 0.35, y: 5.18, w: 8.7, h: 0.24, fontFace: 'Arial', fontSize: 10, color: '4B5D70'
  });
  addPageBadge(slide, 2);
}

// Slide 3 - Speed
{
  const slide = pres.addSlide();
  addHeader(slide,
    'gpt-oss-120B Tops Output Speed at 218 Tokens/s -- More Than 4x Faster Than Claude Opus 4.6',
    'Output speed leaderboard (Muse Spark excluded: no speed data)'
  );

  const labels = ['gpt-oss-120B','Grok 4.20','Nemotron 3','Gemini 3 Flash','Gemini 3.1 Pro','GPT-5.4','GLM-5.1','Claude Sonnet 4.6','Claude Opus 4.6','DeepSeek V3.2'];
  const vals = [218,188,172,153,118,83,64,63,49,46];

  slide.addChart(pres.ChartType.bar, [{ name: 'Output tokens/s', labels, values: vals }], {
    x: 0.4, y: 1.25, w: 6.4, h: 3.9,
    barDir: 'col',
    catAxisLabelRotate: -35,
    catAxisLabelSize: 9,
    valAxisMinVal: 0,
    valAxisMaxVal: 230,
    valAxisMajorUnit: 25,
    showValue: true,
    showLegend: false,
    chartColors: ['2E75B6']
  });

  const speedRows = [
    ['Model','Output tokens/s'],
    ['gpt-oss-120B (high)','218'],
    ['Claude Opus 4.6 (max)','49'],
    ['GPT-5.4 (xhigh)','83'],
    ['Gemini 3.1 Pro Preview','118']
  ];
  slide.addTable(speedRows, {
    x: 6.95, y: 1.4, w: 2.6, h: 2.0,
    fontFace: 'Arial', fontSize: 9,
    border: { pt: 1, color: 'D6DEE8' },
    colW: [1.9,0.7]
  });

  slide.addText('Throughput skews toward open-weight / smaller models; intelligence leaders sit mid-pack on speed.', {
    x: 6.95, y: 3.75, w: 2.6, h: 1.0, fontFace: 'Arial', fontSize: 10, color: '4B5D70'
  });
  addPageBadge(slide, 3);
}

// Slide 4 - Pricing
{
  const slide = pres.addSlide();
  addHeader(slide,
    'From $0.30 to $10 per Million Tokens: A 33x Pricing Gap Across Models',
    'Published API pricing (10 models; Muse Spark excluded)'
  );

  const labels = ['gpt-oss-120B','DeepSeek V3.2','Nemotron 3','Gemini 3 Flash','GLM-5.1','Grok 4.20','Gemini 3.1 Pro','GPT-5.4','Claude Sonnet 4.6','Claude Opus 4.6'];
  const vals = [0.30,0.30,0.40,1.10,2.10,3.00,4.50,5.60,6.00,10.00];

  slide.addChart(pres.ChartType.bar, [{ name: 'USD per 1M tokens', labels, values: vals }], {
    x: 0.4, y: 1.25, w: 6.4, h: 3.9,
    barDir: 'col',
    catAxisLabelRotate: -35,
    catAxisLabelSize: 9,
    valAxisMinVal: 0,
    valAxisMaxVal: 10,
    valAxisMajorUnit: 1,
    showValue: true,
    showLegend: false,
    chartColors: ['1F4E79']
  });

  slide.addText('Cheapest: gpt-oss-120B and DeepSeek V3.2 at $0.30/M\nMost expensive: Claude Opus 4.6 at $10.00/M\nPrice spread: 33x', {
    x: 6.95, y: 1.5, w: 2.6, h: 1.6,
    fontFace: 'Arial', fontSize: 10, color: '1F2D3D'
  });
  slide.addText('Mid-range value callout:\nGemini 3 Flash = $1.10/M, 153 tokens/s, intelligence 46.', {
    x: 6.95, y: 3.25, w: 2.6, h: 1.2,
    fontFace: 'Arial', fontSize: 10, color: '4B5D70'
  });
  addPageBadge(slide, 4);
}

// Slide 5 - Tradeoffs
{
  const slide = pres.addSlide();
  addHeader(slide,
    'No Model Wins on All Three Axes: Navigating the Intelligence-Efficiency-Cost Frontier',
    'Intelligence vs output tokens consumed during evaluation (not throughput in tokens/s)'
  );

  slide.addImage({
    path: '/app/benchmark/assets/chart_intelligence_vs_output_tokens.jpg',
    x: 0.35, y: 1.2, w: 5.9, h: 3.8
  });

